const CHILE: FieldSeed[] = [
  { key: 'documentNumber', type: 'text', label: 'RUT', isRequired: true, sortOrder: 10, helpText: 'Con o sin puntos y guion. Ejemplo: 12.345.678-5.', errorMessage: 'Ingresa un RUT válido (por ejemplo, 12.345.678-5).', requiredMessage: 'Ingresa tu RUT.', rules: [{ kind: 'pattern', pattern: '^[0-9]{1,2}\\.?[0-9]{3}\\.?[0-9]{3}-?[0-9kK]$' }, { kind: 'rutCheckDigit' }, { kind: 'maxLength', value: 12 }] },
