  describe('US-04-AC-25 typed date: the mask, key by key (Colombia)', () => {
    const rows: [string, string][] = [
      ['15051990', '15/05/1990'],
      ['15/05/1990', '15/05/1990'],
      ['15-05-1990', '15/05/1990'],
      ['150', '15/0'],
      ['5/5/1990', '05/05/1990'],
      ['15a05b1990', '15/05/1990'],
      ['150519901', '15/05/1990'],
    ];

    it.each(rows)('US-04-AC-25 typing the keys "%s" one at a time shows "%s"', async (keys, shown) => {
      await start('/co/datos');
      await typeKeys(date(), keys);
      expect(date().value).toBe(shown);
    });

    it('US-04-AC-25 the text box has inputmode numeric, maxlength 10 and the placeholder "dd/mm/aaaa"', async () => {
      await start('/co/datos');
      expect(date().getAttribute('inputmode')).toBe('numeric');
      expect(date().getAttribute('maxlength')).toBe('10');
      expect(date().getAttribute('placeholder')).toBe('dd/mm/aaaa');
    });

    it('US-04-AC-25 Backspace over a separator: from "15/05/1990" at the end, 4 Backspaces show "15/05" and a fifth shows "15/0"', async () => {
      await start('/co/datos');
      await typeDate('15/05/1990');
      const backspace = async (): Promise<void> => {
        // the browser removes the last character, then the input event reaches the mask
        typeInto(date(), date().value.slice(0, -1));
        await settleUi();
      };
      for (let i = 0; i < 4; i++) await backspace();
      expect(date().value).toBe('15/05');
      await backspace();
      expect(date().value).toBe('15/0');
    });

    it.each([
      ['15/05/1990', '15/05/1990'],
      ['15-05-1990', '15/05/1990'],
      ['15.05.1990', '15/05/1990'],
      ['15051990', '15/05/1990'],
      ['5/5/1990', '05/05/1990'],
    ])('US-04-AC-25 pasting "%s" (one input event with the whole text) shows "%s"', async (pasted, shown) => {
      await start('/co/datos');
      await typeDate(pasted);
      expect(date().value).toBe(shown);
    });

    const messageRows: [string, string, string, string | null][] = [
      ['15051990', '15/05/1990', '1990-05-15', null],
      ['29202001', '29/20/2001', '', UNREADABLE],
      ['31021990', '31/02/1990', '', UNREADABLE],
      ['29022001', '29/02/2001', '', UNREADABLE],
      ['1505199', '15/05/199', '', UNREADABLE],
      ['1505', '15/05', '', UNREADABLE],
      ['', '', '', REQUIRED],
      ['01032010', '01/03/2010', '2010-03-01', UNDERAGE],
    ];

    it.each(messageRows)('US-04-AC-25 typing "%s" and leaving shows "%s", the state holds "%s", and the message is %s', async (typed, shown, storedIso, message) => {
      await start('/co/datos');
      await typeKeys(date(), typed);
      await leaveDate();
      expect(date().value).toBe(shown);
      expect(stored('birthDate')).toBe(storedIso);
      if (message === null) {
        expect(date().getAttribute('aria-invalid')).not.toBe('true');
        expect(describedText(date())).not.toContain(UNREADABLE);
      } else {
        expect(date().getAttribute('aria-invalid')).toBe('true');
        expect(describedText(date())).toContain(message);
      }
      if (message !== UNREADABLE) expect(describedText(date())).not.toContain(UNREADABLE);
    });

    it('US-04-AC-25 an unreadable date never shows the required message (the old "Ingresa tu fecha de nacimiento." for "29/20/2001")', async () => {
      await start('/co/datos');
      await typeKeys(date(), '29202001');
      await leaveDate();
      expect(describedText(date())).not.toContain(REQUIRED);
    });

    it('US-04-AC-25 no message while typing: "150" without leaving the field shows no message and is not aria-invalid', async () => {
      await start('/co/datos');
      await typeKeys(date(), '150');
      expect(date().value).toBe('15/0');
      expect(date().getAttribute('aria-invalid')).not.toBe('true');
      expect(describedText(date())).not.toContain(UNREADABLE);
      expect(describedText(date())).not.toContain(REQUIRED);
    });

    it('US-04-AC-25 an invalid date blocks "Continuar": it stays on /co/datos, the focus is on the date box and it is described by the message', async () => {
      await start('/co/datos');
      await fillForm(app.root, { ...CO_VALID_INPUT, [LABEL]: null });
      await typeKeys(date(), '29202001');
      (app.root.querySelector('form') as HTMLFormElement).requestSubmit();
      await app.settle();
      expect(app.path()).toBe('/co/datos');
      expect(document.activeElement).toBe(date());
      expect(describedText(date())).toContain(UNREADABLE);
      expect(stored('birthDate')).toBe('');
    });

    it('US-04-AC-25 a typed date completes step 1: "15/05/1990" typed key by key (no calendar) reaches /co/planes with birthDate 1990-05-15', async () => {
      await start('/co/datos');
      await fillForm(app.root, { ...CO_VALID_INPUT, [LABEL]: null });
      await typeKeys(date(), '15/05/1990');
      await leaveDate();
      (app.root.querySelector('form') as HTMLFormElement).requestSubmit();
      await app.settle();
      expect(app.path()).toBe('/co/planes');
      expect(stored('birthDate')).toBe('1990-05-15');
    });
  });

  // -------------------------------------------------------------------------------------------
}

describe('US-04-AC-25 the date box formats as I type (every row of the AC table, key by key)', () => {
  const rows: [string, string][] = [
    ['15051990', '15/05/1990'],
    ['15/05/1990', '15/05/1990'],
    ['15-05-1990', '15/05/1990'],
    ['150', '15/0'],
    ['5/5/1990', '05/05/1990'],
    ['15a05b1990', '15/05/1990'],
    ['150519901', '15/05/1990'],
  ];

  it.each(rows)('US-04-AC-25 typing "%s" shows "%s"', (keys, shown) => {
    expect(typeKeys(keys)).toBe(shown);
  });

  it('US-04-AC-25 a separator is not shown until the next group has a digit ("15" stays "15", "15/" is "15", "150" is "15/0")', () => {
    expect(typeKeys('15')).toBe('15');
    expect(typeKeys('15/')).toBe('15');
    expect(typeKeys('1505')).toBe('15/05');
    expect(typeKeys('1505/')).toBe('15/05');
  });

  it('US-04-AC-25 a separator pads a one-digit day or month to two digits, and an empty group ignores it', () => {
    expect(typeKeys('5/')).toBe('05');
    expect(typeKeys('5/5/')).toBe('05/05');
    expect(typeKeys('/')).toBe('');
    expect(typeKeys('//')).toBe('');
  });

  it('US-04-AC-25 an empty text stays empty and never gains a separator', () => {
    expect(maskDateDigits('', 0)).toEqual({ text: '', caret: 0 });
  });

  it('US-04-AC-25 at most 8 digits are kept (the ninth is dropped), so the text is at most 10 characters (maxlength 10)', () => {
    expect(maskDateDigits('1505199012', 10).text).toBe('15/05/1990');
    expect(maskDateDigits('15/05/19901', 11).text).toBe('15/05/1990');
  });
});

describe('US-04-AC-25 Backspace over a separator', () => {
  it('US-04-AC-25 "15/05/1990", End, Backspace 4 times shows "15/05"; once more shows "15/0"', () => {
    expect(backspace('15/05/1990', 4)).toBe('15/05');
    expect(backspace('15/05/1990', 5)).toBe('15/0');
  });

  it('US-04-AC-25 each Backspace removes one digit or one separator at most (no digit is lost twice)', () => {
    expect(backspace('15/05/1990', 1)).toBe('15/05/199');
    expect(backspace('15/05/1990', 3)).toBe('15/05/1');
    expect(backspace('15/05/1990', 6)).toBe('15');
  });
});

describe('US-04-AC-25 pasting a date (the whole text arrives in one event, as with Playwright fill())', () => {
  const rows: [string, string][] = [
    ['15/05/1990', '15/05/1990'],
    ['15-05-1990', '15/05/1990'],
    ['15.05.1990', '15/05/1990'],
    ['15051990', '15/05/1990'],
    ['5/5/1990', '05/05/1990'],
  ];

  it.each(rows)('US-04-AC-25 pasting "%s" shows "%s" with the caret at the end', (pasted, shown) => {
    expect(maskDateDigits(pasted, pasted.length)).toEqual({ text: shown, caret: shown.length });
  });

  it('US-04-AC-25 a masked text is a fixed point (masking it again changes nothing)', () => {
    for (const text of ['', '15', '15/0', '15/05', '15/05/1', '15/05/1990', '05/05/1990']) {
      expect(maskDateDigits(text, text.length).text).toBe(text);
    }
  });
});

describe('US-04-AC-25 the caret follows the digits', () => {
  it('US-04-AC-25 at the end of the raw text the caret goes to the end of the masked text', () => {
    expect(maskDateDigits('1505', 4)).toEqual({ text: '15/05', caret: 5 });
    expect(maskDateDigits('15051990', 8)).toEqual({ text: '15/05/1990', caret: 10 });
  });

  it('US-04-AC-25 elsewhere the caret stays right after the same number of digits it followed', () => {
    // "15/05/1990" with a 9 typed after "15/0": raw "15/095/1990", caret 5 (after the 9, 4 digits before it)
    const out = maskDateDigits('15/095/1990', 5);
    expect(out.text).toBe('15/09/5199');
    expect(out.caret).toBe(5);
    expect(maskDateDigits('1505', 1)).toEqual({ text: '15/05', caret: 1 });
    expect(maskDateDigits('1505', 0)).toEqual({ text: '15/05', caret: 0 });
